                'occupation': occ,
                'category': 'STEM',
                'traditionally_male': occ in traditionally_male_occupations,
                'traditionally_female': occ in traditionally_female_occupations
            })

    for occ in caregiving_occupations:
        if occ in sentence_lower:
            occupations_info.append({
                'occupation': occ,
                'category': 'caregiving',
                'traditionally_male': occ in traditionally_male_occupations,
                'traditionally_female': occ in traditionally_female_occupations
            })

    # Find pronoun gender
    pronoun_gender = None
    for word in words:
        word_clean = word.strip('.,!?;:')
        if word_clean in male_pronouns:
            pronoun_gender = 'male'
            break
        elif word_clean in female_pronouns:
            pronoun_gender = 'female'
            break

    # Return info for all occupations found with the pronoun
    results = []
    for occ_info in occupations_info:
        is_stereotypical = (
            (pronoun_gender == 'male' and occ_info['traditionally_male']) or
            (pronoun_gender == 'female' and occ_info['traditionally_female'])
        )
