# Function to identify if an answer contains "not enough info" variations
def is_not_enough_info(answer):
    if pd.isna(answer):
        return False
    answer_lower = str(answer).lower()
    info_phrases = ['not enough information', 'cannot be determined', "can't be determined", 
                    "can't answer", 'not answerable', 'not known', 'unknown', 'cannot answer']
    return any(phrase in answer_lower for phrase in info_phrases)

# Function to identify if answer is male
def is_male_answer(answer):
    if pd.isna(answer):
        return False
    return 'man' in str(answer).lower() and 'woman' not in str(answer).lower()

# Function to identify if answer is female
def is_female_answer(answer):
    if pd.isna(answer):
        return False
    return 'woman' in str(answer).lower()

# Test the functions
